fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n < 4 {
                // If n is less than 4, we need to add enough items to reach 4.
                4 - n
            } else {
                // Otherwise, we only need to add 0 if n is even, 1 if n is odd.
                n % 2
            }
        })
        .collect()
}

